const payload = $input.first().json.body ?? $input.first().json;
const recordId = payload.recordId;
if (!recordId) throw new Error('recordId is required.');

function plain(value) {
  if (value == null) return '';
  if (typeof value === 'object' && !Array.isArray(value) && value.name != null) return String(value.name);
  return String(value);
}

function count(value, fallback = 1) {
  const parsed = Number(plain(value).match(/\d+/)?.[0] ?? fallback);
  return Math.max(1, Math.min(10, Number.isFinite(parsed) ? parsed : fallback));
}

const sources = [1, 2, 3, 4].map(step => {
  const subject = plain(payload[`Subject Line Email ${step} (Review)`]).trim();
  const body = plain(payload[`Script Copy Email ${step} (Review)`]).trim();
  const requestedVariants = count(payload[`Number of variants - Step ${step}`], 1);
  return {step, subject, body, requestedVariants};
}).filter(email => email.subject || email.body);

if (!sources.length) throw new Error('No approved Email 1-4 review copy was provided.');
return [{json: {recordId, sourceEmails: sources}}];

