function lockApprovedNumbers(text, approved){
 return String(text).replace(/\{([^{}]*\|[^{}]*)\}/g,(group,inner)=>{
   const options=inner.split('|').map(x=>x.trim());
   if(!options.some(x=>/\d/.test(x)))return group;
   const original=options.find(x=>String(approved).includes(x));
   return original||group;
 });
}
function spinQuality(row){try{return checkedSpinQuality(row);}catch(error){return {spintaxValid:false,spintaxIssue:error.message,spintaxGroups:0,bodySpintaxGroups:0,spintaxCombinations:0};}}

function spinStats(value) {
  const text=String(value||''); let groups=0, substantive=0, combinations=1;
  const masked=text.replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g,(whole,name)=>'\uE000'+name+'\uE001');
  const rest=masked.replace(/\{([^{}]*)\}/g,(whole,inside,offset)=>{
    if(!inside.includes('|'))return whole;
    const options=inside.split('|').map(x=>x.trim());
    if(options.length>4||options.some(x=>!x)||new Set(options.map(x=>x.toLowerCase())).size!==options.length)throw new Error('Spintax has empty or duplicate alternatives');
    const tagSignatures=options.map(option=>[...option.matchAll(/\uE000([A-Za-z_][A-Za-z0-9_]*)\uE001/g)].map(x=>x[1]).sort().join('|'));
    if(new Set(tagSignatures).size!==1)throw new Error('Merge tags inside spintax must appear unchanged in every alternative');
    groups++; combinations=Math.min(Number.MAX_SAFE_INTEGER,combinations*options.length);
    if(!options.every(x=>/^(hi|hey|hello|dear|thanks|thank you|best|regards|cheers)[!, .]*$/i.test(x)))substantive++;
    return '';
  });
  if(/[{}]/.test(rest))throw new Error('Malformed or nested spintax');
  return {groups,substantive,combinations};
}
function checkedSpinQuality(row){
  if(/\{[^{}]*\d[^{}]*\|[^{}]*\}|\{[^{}]*\|[^{}]*\d[^{}]*\}/.test(String(row.body)+' '+String(row.subject)))throw new Error('Keep approved numbers and time commitments fixed outside spintax groups');
  const b=spinStats(row.body),s=spinStats(row.subject);
  const words=String(row.approvedBody||row.body||'').split(/\s+/).filter(Boolean).length;
  const targetGroups=words>=150?6:words>=100?5:words>=50?4:3;
  const targetCombinations=words>=50?32:18;
  const tagPath=t=>{
    const masked=String(t||'').replace(/\{([A-Za-z_][A-Za-z0-9_]*)\}/g,(whole,name)=>'\uE000'+name+'\uE001');
    const firstPath=masked.replace(/\{([^{}]*)\}/g,(whole,inside)=>inside.includes('|')?inside.split('|')[0]:whole);
    return [...firstPath.matchAll(/\uE000([A-Za-z_][A-Za-z0-9_]*)\uE001/g)].map(x=>x[1]).sort().join('|');
  };
  if(tagPath(row.body)!==tagPath(row.approvedBody)||tagPath(row.subject)!==tagPath(row.approvedSubject))throw new Error('Merge tags differ from approved copy');
  const totalCombinations=Math.min(Number.MAX_SAFE_INTEGER,b.combinations*s.combinations);
  const densityMet=b.substantive>=targetGroups&&totalCombinations>=targetCombinations;
  return {spintaxGroups:b.groups+s.groups,bodySpintaxGroups:b.substantive,spintaxCombinations:totalCombinations,spintaxValid:true,spintaxIssue:'',spintaxDensityTargetGroups:targetGroups,spintaxDensityTargetCombinations:targetCombinations,spintaxDensityMet:densityMet};
}

function parts(text){
 const clean=String(text||'').replace(/\\_/g,'_').trim();
 const matches=[...clean.matchAll(/(?:^|\n)[ \t]*(?:Variant[ \t]+([A-J]|\d+)[ \t]*[:.)-]?|(\d+)[ \t]*[-.)])[ \t]*(?:\r?\n|$)/gi)];
 if(!matches.length)return [clean];
 if(clean.slice(0,matches[0].index).trim())throw new Error('Unexpected text before approved variant heading');
 return matches.map((m,i)=>{
  const label=(m[1]||m[2]).toUpperCase();
  const ordinal=/^[A-J]$/.test(label)?label.charCodeAt(0)-64:Number(label);
  if(ordinal!==i+1)throw new Error('Approved variant headings must be unique and sequential');
  const body=clean.slice(m.index+m[0].length,matches[i+1]?.index??clean.length).trim();
  if(!body)throw new Error('Approved variant is empty');
  return body;
 });
}

const normalized=$('Normalize Campaign Input').first().json;
const reviewed=$input.first().json.output;
if(!reviewed||!Array.isArray(reviewed.variants))throw new Error('Reviewed GPT sequence missing; never substitute original unspun copy');
const expected=new Map();
for(const email of normalized.sourceEmails){
 const bodies=parts(email.body),subjects=parts(email.subject);
 const count=Math.max(1,Math.min(10,Number(email.requestedVariants)||1));
  if(subjects.length!==1&&subjects.length!==count)throw new Error('Approved subject variant count mismatch');
 if(bodies.length!==1&&bodies.length!==count)throw new Error('Approved variant count mismatch');
 for(let i=0;i<count;i++)expected.set(Number(email.step)+':'+String.fromCharCode(65+i),{approvedBody:bodies[bodies.length===1?0:i],approvedSubject:subjects[subjects.length===count?i:0]});
}
const seen=new Set();
const rows=reviewed.variants.map(v=>{
 const step=Number(v.step),rawVariant=String(v.variant).trim().toUpperCase();
 const variant=/^(?:10|[1-9])$/.test(rawVariant)?String.fromCharCode(64+Number(rawVariant)):rawVariant;
 const key=step+':'+variant;
 if(!expected.has(key)||seen.has(key))throw new Error('Unexpected or duplicated GPT step/variant '+key);
 seen.add(key);
 if(typeof v.subject!=='string'||typeof v.body!=='string'||!v.body.trim())throw new Error('GPT copy is incomplete');
 const row={recordId:normalized.recordId,step,variant,subject:v.subject.replace(/\\_/g,'_').trim(),body:v.body.replace(/\\_/g,'_').trim(),...expected.get(key)};
 row.body=lockApprovedNumbers(row.body,row.approvedBody);row.subject=lockApprovedNumbers(row.subject,row.approvedSubject);
 return {json:{...row,...spinQuality(row)}};
});
if(seen.size!==expected.size)throw new Error('GPT sequence is missing requested variants');
return rows;

