const statusItems = (() => {
const results = $input.all().map(item => item.json);
if (!results.length) throw new Error('No validated variants reached the final update.');

const stripGeneratedLabel = (value) => String(value ?? '')
  .replace(/^\s*(?:(?:variant|email)\s*#?\s*(?:\d+|[A-Z])|step\s*#?\s*\d+(?:\s*variant\s*#?\s*[A-Z])?)\s*(?:[:\-–—])?\s*(?:\r?\n)+/i, '')
  .trimStart();

const recordId = results[0].recordId;
const expected = $('Prepare Variant Checks').all().map(x=>x.json);
const seen=new Set();
for(const r of results){const key=r.step+':'+r.variant;if(r.recordId!==recordId||seen.has(key))throw new Error('QA result identity or duplicate mismatch');seen.add(key);}
