  'Improvement Sugestion':'',
};

for (const result of results) {
  const step = Number(result.step);
  const variant = String(result.variant || 'a').toLowerCase();
  const version = Math.max(1, variant.charCodeAt(0) - 96);
  const subject = String(result.subject ?? '');
  const body = stripGeneratedLabel(result.body);

  if (step === 1) {
    const subjectField = version === 1
      ? 'Campaign Email 1 Subject Version 1'
      : `Campaign Subject 1 Version ${version}`;
    fields[subjectField] = subject;
    fields[`Campaign Body 1 Version ${version}`] = body;
  } else if (step === 2) {
    fields['Campaign Email 2 Subject'] = subject;
    fields['Campaign Body 2 Version 1'] = body;
  } else if (step === 3) {
    fields['Campaign Email 3 Subject'] = subject;
    fields['Campaign Body 3 Version 1'] = body;
  } else if (step === 4) {
    const subjectField = version === 1
      ? 'Campaign Email 4 Subject'
      : `Campaign Email 4 Subject Version ${version}`;
    fields[subjectField] = subject;
    fields[`Campaign Body 4 Version ${version}`] = body;
  }
}

